// Independent reader of the frozen collector's accepted source records.
// It neither imports the producer nor uses its witness/filter implementation.
use std::fs;
const P:i64=1009;const N:i64=1013;const SMALL:usize=8;const LARGE:usize=16;const QCOL:usize=24;const RHS:usize=25;
#[derive(Clone,Copy,Eq,PartialEq,Debug)]enum Pt{O,A(i64,i64)}
fn m(x:i64,n:i64)->i64{x.rem_euclid(n)}
fn inv(x:i64,n:i64)->i64{let(mut a,mut b,mut u,mut v)=(m(x,n),n,1,0);while b!=0{let q=a/b;(a,b)=(b,a-q*b);(u,v)=(v,u-q*v)}assert_eq!(a,1);m(u,n)}
fn plus(a:Pt,b:Pt)->Pt{match(a,b){(Pt::O,v)|(v,Pt::O)=>v,(Pt::A(x,y),Pt::A(u,v))=>{if x==u&&m(y+v,P)==0{return Pt::O}let s=if x==u{m((3*x*x+1)*inv(2*y,P),P)}else{m((v-y)*inv(u-x,P),P)};let xx=m(s*s-x-u,P);Pt::A(xx,m(s*(x-xx)-y,P))}}}
fn mul(mut k:i64,mut q:Pt)->Pt{if k<0{k=-k;q=match q{Pt::O=>Pt::O,Pt::A(x,y)=>Pt::A(x,m(-y,P))}}let mut out=Pt::O;while k>0{if k&1!=0{out=plus(out,q)}q=plus(q,q);k>>=1}out}
fn val(t:&str,p:&str)->i64{t.strip_prefix(p).unwrap().parse().unwrap()}
fn base()->Vec<Pt>{let mut out=Vec::new();for x in 0..P{for y in 0..P{if m(y*y-x*x*x-x-14,P)==0{out.push(Pt::A(x,y));break}}if out.len()==SMALL+LARGE{break}}out}
fn rref(rows:&[Vec<i64>])->(usize,Option<i64>){let mut z=rows.to_vec();let mut h=0;for col in 0..=QCOL{if let Some(k)=(h..z.len()).find(|&i|z[i][col]!=0){z.swap(h,k);let p=inv(z[h][col],N);for j in col..=RHS{z[h][j]=m(z[h][j]*p,N)}let pivot=z[h].clone();for i in 0..z.len(){if i!=h{let q=z[i][col];for j in col..=RHS{z[i][j]=m(z[i][j]-q*pivot[j],N)}}}h+=1}}let ans=z.iter().find(|r|(0..QCOL).all(|j|r[j]==0)&&r[QCOL]!=0).map(|r|m(r[RHS]*inv(r[QCOL],N),N));(h,ans)}
fn main(){let raw=fs::read_to_string("WS68_NATURAL_PARTIAL.stdout").unwrap();let b=base();let g=b[0];assert_eq!(g,Pt::A(0,425));let q=mul(701,g);assert_eq!(q,Pt::A(779,357));let mut blocks:Vec<Vec<Vec<i64>>>=vec![Vec::new()];let mut counts=[[0usize;3];2];let mut lines=0;
 for line in raw.lines(){if !line.starts_with("source "){continue}let t:Vec<&str>=line.split_whitespace().collect();assert_eq!(t.len(),10);let id=val(t[1],"id=")as usize;if id==0&&lines>0{blocks.push(Vec::new())}let arm=blocks.len()-1;assert!(arm<2);assert_eq!(id,blocks[arm].len());let a=val(t[3],"a=");let bb=val(t[4],"b=");let x:i64=t[5].strip_prefix("r=A(").unwrap().trim_end_matches(',').parse().unwrap();let y=t[6].trim_end_matches(')').parse().unwrap();let r=Pt::A(x,y);let kind=t[7].strip_prefix("kind=").unwrap();let i=val(t[8],"i=")as usize;let j=val(t[9],"j=")as usize;assert!(i<SMALL+LARGE&&j<SMALL+LARGE);let ki=match kind{"Full"=>0,"One"=>1,"Two"=>2,_=>panic!("kind")};counts[arm][ki]+=1;assert_eq!(plus(b[i],b[j]),r);assert_eq!(plus(mul(a,g),mul(bb,q)),r);assert_eq!(m(y*y-x*x*x-x-14,P),0);let mut row=vec![0i64;RHS+1];row[i]+=1;row[j]+=1;row[QCOL]=m(-bb,N);row[RHS]=a;blocks[arm].push(row);lines+=1}
 assert_eq!(blocks.len(),2);assert_eq!(counts,[[17,0,0],[17,68,67]]);let mut anchor=vec![0;RHS+1];anchor[0]=1;anchor[RHS]=1;for (arm,rows) in blocks.iter_mut().enumerate(){rows.insert(0,anchor.clone());let (rank,ans)=rref(rows);assert_eq!(ans,Some(701));let expected=if arm==0{9}else{25};assert_eq!(rank,expected);println!("arm={} source_rows={} source_identities_verified={} rank_full_variables={rank} target_pinned=true recovered={}",if arm==0{"full_only"}else{"partial_filter"},rows.len()-1,rows.len()-1,ans.unwrap())}println!("source_lines={lines} counts_full_one_two={counts:?} independent_source_and_point_check=true");}
